  if (--r->threads_left <= 0)
    {
      r->finished = 1;
    }

  asr_race_unlock(r);

  if (__atomic_sub_fetch(&r->refs, 1, __ATOMIC_ACQ_REL) == 0)
    {
      free_now = 1;
    }

  if (free_now)
    {
      sem_destroy(&r->lock);
      free((void *)r->pcm);
      free(r);
    }
}

